#!/usr/bin/env python3
"""CLI tool for managing resources across microservices.
Authenticates via service tokens and manages user resources."""

import hashlib
import hmac
import json
import os
import time
import secrets
from dataclasses import dataclass, field
from typing import Optional, Dict, List

SERVICE_SECRET = os.environ.get("SERVICE_SECRET", "default-dev-secret-key")
TOKEN_TTL = 300  # 5 minutes

@dataclass
class ServiceToken:
    user_id: str
    service: str
    issued_at: float
    nonce: str
    signature: str = ""

    def compute_signature(self, secret: str) -> str:
        payload = f"{self.user_id}:{self.service}:{self.issued_at}:{self.nonce}"
        return hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()

    def is_valid(self, secret: str) -> bool:
        expected = self.compute_signature(secret)
        return hmac.compare_digest(expected, self.signature)

    def is_expired(self) -> bool:
        return (time.time() - self.issued_at) > TOKEN_TTL


@dataclass
class Resource:
    resource_id: str
    owner_id: str
    service: str
    data: dict = field(default_factory=dict)


class ResourceStore:
    def __init__(self):
        self._resources: Dict[str, Resource] = {}

    def add(self, resource: Resource):
        self._resources[resource.resource_id] = resource

    def get(self, resource_id: str) -> Optional[Resource]:
        return self._resources.get(resource_id)

    def list_for_user(self, user_id: str, service: str) -> List[Resource]:
        return [
            r for r in self._resources.values()
            if r.owner_id == user_id and r.service == service
        ]


class AuthContext:
    """Manages authentication context for cross-service requests."""

    def __init__(self, token: ServiceToken):
        self._token = token
        self._validated = False
        self._effective_user_id: Optional[str] = None

    def validate(self) -> bool:
        if self._token.is_expired():
            return False
        if not self._token.is_valid(SERVICE_SECRET):
            return False
        self._validated = True
        self._effective_user_id = self._token.user_id
        return True

    @property
    def effective_user_id(self) -> Optional[str]:
        return self._effective_user_id

    @property
    def service(self) -> str:
        return self._token.service

    def elevate_for_service(self, target_user_id: str, requesting_service: str) -> bool:
        """Allow service-to-service elevation for delegated operations.
        Only the 'admin-service' can elevate to act on behalf of another user."""
        if not self._validated:
            return False
        if requesting_service == "admin-service":
            self._effective_user_id = target_user_id
            return True
        return False


class ResourceManager:
    """Handles resource operations with authorization checks."""

    def __init__(self, store: ResourceStore):
        self._store = store

    def get_resource(self, auth: AuthContext, resource_id: str) -> Optional[Resource]:
        resource = self._store.get(resource_id)
        if resource is None:
            return None
        if not self._check_access(auth, resource):
            return None
        return resource

    def _check_access(self, auth: AuthContext, resource: Resource) -> bool:
        """Verify the authenticated user has access to the resource.
        Access is granted if:
        1. The effective user matches the resource owner, OR
        2. The requesting service matches the resource's service
        """
        if auth.effective_user_id == resource.owner_id:
            return True
        if auth.service == resource.service:
            return True
        return False

    def list_resources(self, auth: AuthContext) -> List[Resource]:
        return self._store.list_for_user(auth.effective_user_id, auth.service)


def create_token(user_id: str, service: str) -> ServiceToken:
    token = ServiceToken(
        user_id=user_id,
        service=service,
        issued_at=time.time(),
        nonce=secrets.token_hex(16)
    )
    token.signature = token.compute_signature(SERVICE_SECRET)
    return token


def handle_request(action: str, token_data: dict, params: dict) -> dict:
    """Main request handler for the CLI tool."""
    try:
        token = ServiceToken(**token_data)
    except (TypeError, KeyError):
        return {"error": "Invalid token format"}

    auth = AuthContext(token)
    if not auth.validate():
        return {"error": "Authentication failed"}

    store = ResourceStore()
    # Seed some test data
    store.add(Resource("res-001", "user-alice", "storage-service", {"file": "secret.txt"}))
    store.add(Resource("res-002", "user-bob", "storage-service", {"file": "private.doc"}))
    store.add(Resource("res-003", "user-alice", "compute-service", {"vm": "prod-1"}))

    manager = ResourceManager(store)

    if action == "get":
        resource_id = params.get("resource_id")
        if not resource_id:
            return {"error": "Missing resource_id"}
        resource = manager.get_resource(auth, resource_id)
        if resource is None:
            return {"error": "Not found or access denied"}
        return {"resource": resource.data}

    elif action == "list":
        resources = manager.list_resources(auth)
        return {"resources": [r.data for r in resources]}

    elif action == "delegate":
        target_user = params.get("target_user")
        if not target_user:
            return {"error": "Missing target_user"}
        if auth.elevate_for_service(target_user, auth.service):
            resource_id = params.get("resource_id")
            resource = manager.get_resource(auth, resource_id)
            if resource:
                return {"resource": resource.data}
        return {"error": "Delegation denied"}

    return {"error": "Unknown action"}


if __name__ == "__main__":
    import sys
    if len(sys.argv) < 2:
        print("Usage: cli.py <action> [params...]")
        sys.exit(1)

    # Demo: alice accessing her own resource via storage-service
    token = create_token("user-alice", "storage-service")
    token_dict = {
        "user_id": token.user_id,
        "service": token.service,
        "issued_at": token.issued_at,
        "nonce": token.nonce,
        "signature": token.signature
    }
    result = handle_request("get", token_dict, {"resource_id": "res-001"})
    print(json.dumps(result, indent=2))
